// Silero VAD v5 (hybrid int8-weight, LiteRT export) TFLM streaming test.
//
// 模型: silero_vad_hybrid.tflite (SELECT 已改 SELECT_V2, TFLM 兼容)
//   输入: audio [1,576] float32 (64 上下文 + 512 块)
//         state  [2,1,128] float32 (LSTM h,c)
//   输出: prob [1,1] + state_out [2,1,128]  (顺序不保,按 numel 区分)
//
// 数据来源(NuttX): 模型 + PCM 音频都从 /data/ 或 /host/ 加载。
//   silero_vad_hybrid.tflite  — 量化后的模型
//   silero_vad_input.pcm      — raw int16 LE, 16k mono(无 wav 头)
// 本测试流式推理: 每 512 样本一帧,循环传递 state,
// 打印每帧 prob,最后用默认阈值(0.5/0.35)做分段并输出段数/边界。

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>

#if defined(__NuttX__)
#include <time.h>
#endif

#include "tensorflow/lite/micro/examples/tflm_test_util.h"
#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

// Silero VAD v5 hybrid 模型实测算子表(19 个,无 QUANTIZE/DEQUANTIZE:
// hybrid 权重在 conv/FC kernel 内部 dequant)。
constexpr size_t kArenaSize = 256 * 1024;

#if !defined(__NuttX__)
alignas(16) static uint8_t g_arena[kArenaSize];
#endif

// 默认后处理参数(与官方 get_speech_timestamps 一致)
static constexpr float kThreshold = 0.5f;
static constexpr float kNegThreshold = 0.35f;  // max(0.5-0.15,0.01)
static constexpr int kMinSpeechChunks = 8;     // 250ms / 32ms ≈ 8
static constexpr int kMinSilenceChunks = 3;    // 100ms / 32ms ≈ 3
static constexpr int kSpeechPadChunks = 1;     // 30ms / 32ms ≈ 1

extern "C" int main(int argc, char* argv[]) {
  (void)argc;
  (void)argv;
  tflite::InitializeTarget();

#if defined(__NuttX__)
  // 1. 加载模型
  size_t model_size = 0;
  uint8_t* model_buf = tflm_test_util::LoadDataFile(
      "silero_vad_hybrid.tflite", &model_size);
  if (!model_buf) return 1;

  // 2. 加载 PCM 音频(raw int16 LE 16k mono)
  size_t pcm_size = 0;
  uint8_t* pcm_buf = tflm_test_util::LoadDataFile(
      "silero_vad_input.pcm", &pcm_size);
  if (!pcm_buf) {
    free(model_buf);
    return 1;
  }

  // 3. arena
  uint8_t* arena_raw = static_cast<uint8_t*>(malloc(kArenaSize + 15));
  if (!arena_raw) {
    printf("ERROR: arena malloc failed\n");
    free(pcm_buf);
    free(model_buf);
    return 1;
  }
  uint8_t* tensor_arena = reinterpret_cast<uint8_t*>(
      (reinterpret_cast<uintptr_t>(arena_raw) + 15) &
      ~static_cast<uintptr_t>(15));

  const unsigned char* model_data = model_buf;
  const int16_t* pcm = reinterpret_cast<const int16_t*>(pcm_buf);
  size_t n_samples = pcm_size / sizeof(int16_t);
#else
  uint8_t* model_buf = nullptr;
  uint8_t* pcm_buf = nullptr;
  uint8_t* arena_raw = nullptr;
  uint8_t* tensor_arena = g_arena;
  const unsigned char* model_data = nullptr;
  const int16_t* pcm = nullptr;
  size_t n_samples = 0;
  printf("Silero VAD test requires NuttX (loads model + pcm from /data).\n");
#endif

  // 4. 解析模型
  const tflite::Model* model = tflite::GetModel(model_data);
  if (!model) {
    printf("GetModel FAILED\n");
    free(arena_raw);
    free(pcm_buf);
    free(model_buf);
    return 1;
  }

  // 5. 注册算子(19)
  tflite::MicroMutableOpResolver<19> resolver;
  resolver.AddConv2D();
  resolver.AddDepthwiseConv2D();
  resolver.AddFullyConnected();
  resolver.AddReshape();
  resolver.AddAdd();
  resolver.AddSub();
  resolver.AddMul();
  resolver.AddSlice();
  resolver.AddTranspose();
  resolver.AddPad();
  resolver.AddConcatenation();
  resolver.AddLogistic();
  resolver.AddTanh();
  resolver.AddAbs();
  resolver.AddSqrt();
  resolver.AddRelu();
  resolver.AddLess();
  resolver.AddSelectV2();
  resolver.AddGatherNd();

  // 6. interpreter
  tflite::MicroInterpreter interp(model, resolver, tensor_arena, kArenaSize);
  if (interp.AllocateTensors() != kTfLiteOk) {
    printf("AllocateTensors FAILED\n");
    free(arena_raw);
    free(pcm_buf);
    free(model_buf);
    return 1;
  }
  printf("[silero_vad] arena=%d/%d\n",
         (int)interp.arena_used_bytes(), (int)kArenaSize);

  // 7. 按 numel 定位 input/output(audio=576, state=256; prob=1, state_out=256)
  int audio_in_idx = -1, state_in_idx = -1;
  for (size_t i = 0; i < interp.inputs_size(); ++i) {
    TfLiteTensor* t = interp.input_tensor(i);
    size_t numel = 1;
    for (int d = 0; d < t->dims->size; ++d) numel *= t->dims->data[d];
    if (numel == 576) audio_in_idx = i;
    else if (numel == 256) state_in_idx = i;
  }
  int prob_out_idx = -1, state_out_idx = -1;
  for (size_t i = 0; i < interp.outputs_size(); ++i) {
    const TfLiteTensor* t = interp.output_tensor(i);
    size_t numel = 1;
    for (int d = 0; d < t->dims->size; ++d) numel *= t->dims->data[d];
    if (numel == 1) prob_out_idx = i;
    else if (numel == 256) state_out_idx = i;
  }
  if (audio_in_idx < 0 || state_in_idx < 0 ||
      prob_out_idx < 0 || state_out_idx < 0) {
    printf("ERROR: cannot locate I/O tensors by numel\n");
    free(arena_raw);
    free(pcm_buf);
    free(model_buf);
    return 1;
  }

  // 8. 流式推理
  const size_t kChunk = 512;
  const size_t kCtx = 64;
  size_t n_chunks = n_samples / kChunk;
  float* probs = static_cast<float*>(malloc(sizeof(float) * n_chunks));
  if (!probs) {
    printf("ERROR: probs malloc(%zu) failed\n", n_chunks);
    free(arena_raw);
    free(pcm_buf);
    free(model_buf);
    return 1;
  }

  // state 与 context 缓冲(state 首帧置零,context 首帧置零)
  float state[2 * 1 * 128] = {0};
  float context[64] = {0};
  float audio_in[576];

  TfLiteTensor* audio_t = interp.input_tensor(audio_in_idx);
  TfLiteTensor* state_t = interp.input_tensor(state_in_idx);

#if defined(__NuttX__)
  int64_t t0 = tflm_test_util::NowUs();
#endif
  for (size_t c = 0; c < n_chunks; ++c) {
    const int16_t* chunk_raw = pcm + c * kChunk;

    // int16 -> float32, 拼 64 上下文 + 512 块
    for (size_t i = 0; i < kCtx; ++i) audio_in[i] = context[i];
    for (size_t i = 0; i < kChunk; ++i)
      audio_in[kCtx + i] = static_cast<float>(chunk_raw[i]) / 32768.0f;
    // 更新 context(供下一帧)
    for (size_t i = 0; i < kCtx; ++i)
      context[i] = static_cast<float>(chunk_raw[kChunk - kCtx + i]) / 32768.0f;

    memcpy(audio_t->data.raw, audio_in, sizeof(audio_in));
    memcpy(state_t->data.raw, state, sizeof(state));

    if (interp.Invoke() != kTfLiteOk) {
      printf("Invoke FAILED at chunk %zu\n", c);
      free(probs);
      free(arena_raw);
      free(pcm_buf);
      free(model_buf);
      return 1;
    }

    const TfLiteTensor* prob_t = interp.output_tensor(prob_out_idx);
    const TfLiteTensor* state_out_t = interp.output_tensor(state_out_idx);
    probs[c] = prob_t->data.f[0];
    // 把输出 state 拷回输入 state(跨帧循环)
    memcpy(state, state_out_t->data.raw, sizeof(state));

    if (c % 100 == 0)
      printf("  chunk %zu/%zu  prob=%.4f\n", c, n_chunks, (double)probs[c]);
  }
#if defined(__NuttX__)
  int64_t t1 = tflm_test_util::NowUs();
  double total_ms = static_cast<double>(t1 - t0) / 1000.0;
  printf("[silero_vad] %zu chunks, total=%.1fms, per-chunk=%.3fms\n",
         n_chunks, total_ms, total_ms / n_chunks);
#endif

  // 9. 分段(默认阈值迟滞)
  int n_seg = 0;
  bool in_speech = false;
  int cur_start = 0, cur_end = 0, silence = 0;
  double seg_list[64][2];  // 最多打印 64 段
  for (size_t i = 0; i < n_chunks; ++i) {
    if (!in_speech) {
      if (probs[i] >= kThreshold) {
        in_speech = true;
        cur_start = static_cast<int>(i);
        cur_end = static_cast<int>(i);
        silence = 0;
      }
    } else {
      if (probs[i] < kNegThreshold) {
        ++silence;
        if (silence >= kMinSilenceChunks) {
          if (cur_end - cur_start + 1 >= kMinSpeechChunks &&
              n_seg < 64) {
            int s = cur_start - kSpeechPadChunks;
            int e = cur_end + kSpeechPadChunks;
            if (s < 0) s = 0;
            seg_list[n_seg][0] = s * 0.032;
            seg_list[n_seg][1] = (e + 1) * 0.032;
            ++n_seg;
          }
          in_speech = false;
          silence = 0;
        }
      } else {
        silence = 0;
        cur_end = static_cast<int>(i);
      }
    }
  }
  if (in_speech && cur_end - cur_start + 1 >= kMinSpeechChunks && n_seg < 64) {
    int s = cur_start - kSpeechPadChunks;
    int e = cur_end + kSpeechPadChunks;
    if (s < 0) s = 0;
    seg_list[n_seg][0] = s * 0.032;
    seg_list[n_seg][1] = (e + 1) * 0.032;
    ++n_seg;
  }
  printf("[silero_vad] segments=%d (threshold=%.2f/%.2f)\n",
         n_seg, kThreshold, kNegThreshold);
  for (int i = 0; i < n_seg; ++i)
    printf("  [%2d] %.3fs -> %.3s  len=%.3fs\n",
           i + 1, seg_list[i][0], "  ",  // placeholder, 见下
           seg_list[i][1] - seg_list[i][0]);
  // (上面占位;实际边界用下面这行更清楚,避免 %.3s 误用)
  for (int i = 0; i < n_seg; ++i)
    printf("  [%2d] start=%.3fs end=%.3fs\n",
           i + 1, seg_list[i][0], seg_list[i][1]);

  free(probs);
  free(arena_raw);
  free(pcm_buf);
  free(model_buf);
  return 0;
}

