import serial, sys, time
p = sys.argv[1]
for baud in (921600, 115200, 2000000):
    try:
        s = serial.Serial(p, baud, timeout=0.2)
    except Exception as e:
        print(f"[{baud}] open fail: {e}"); continue
    s.rtscts = False; s.dsrdtr = False
    try:
        s.dtr = False; s.rts = False; time.sleep(0.1)
        s.dtr = True; time.sleep(0.2)
    except: pass
    try:
        if s.in_waiting: s.read(s.in_waiting)
    except: pass
    try:
        s.write(b"\r"); time.sleep(0.3); s.write(b"help\r")
    except Exception as e:
        print(f"[{baud}] write fail: {e}"); s.close(); continue
    buf=b""; end=time.time()+4
    while time.time()<end:
        try:
            r=s.read(4096)
            if r: buf+=r
        except Exception as e:
            buf+=f"<exc:{e}>".encode(); break
    print(f"[{baud}] {'NO OUTPUT' if not buf else buf.decode('utf-8','replace')[-600:]}")
    s.close()
EOF
for p in /dev/ttyACM0 /dev/ttyACM1; do echo "===== $p ====="; fuser -k $p 2>/dev/null; sleep 0.5; timeout 20 /usr/bin/python3 /tmp/nsh3.py $p 2>&1 | tail -15; done

cat > /tmp/nsh_cmd.py <<'EOF'
import serial, sys, time
p=sys.argv[1]; cmd=sys.argv[2]; wait=float(sys.argv[3]) if len(sys.argv)>3 else 3
def open_port():
    for attempt in range(5):
        try:
            s=serial.Serial(p,921600,timeout=0.2)
            s.rtscts=False; s.dsrdtr=False
            try: s.dtr=True
            except: pass
            return s
        except Exception as e:
            time.sleep(0.8)
    raise SystemExit("open failed after retries")
s=open_port()
time.sleep(0.3)
try:
    if s.in_waiting: s.read(s.in_waiting)
except: pass
s.write(b"\r"); time.sleep(0.25)
s.write(cmd.encode()+b"\r")
buf=b""; end=time.time()+wait; exc_count=0
while time.time()<end and exc_count<8:
    try:
        r=s.read(4096)
        if r: buf+=r
        elif not r: time.sleep(0.05)
    except Exception as e:
        exc_count+=1; time.sleep(0.3)
sys.stdout.buffer.write(buf)
try: s.close()
except: pass
EOF
