s.rtscts=False; s.dsrdtr=False
try: s.dtr=False; s.rts=False; time.sleep(0.1); s.dtr=True; time.sleep(0.2)
except: pass
try:
    if s.in_waiting: s.read(s.in_waiting)
except: pass
s.write(b"\r"); time.sleep(0.4)
# drain any prompt
try:
    if s.in_waiting: s.read(s.in_waiting)
except: pass
for cmd in cmds:
    s.write(cmd.encode()+b"\r")
    end=time.time()+ (6 if 'silero' in cmd else 1.5)
    buf=b""
    while time.time()<end:
        try:
            r=s.read(4096)
            if r: buf+=r
        except Exception as e:
            buf+=f"<exc:{e}>".encode(); time.sleep(0.3)
    sys.stdout.buffer.write(b"<<<"+cmd.encode()+b">>>\n"+buf+b"\n")
try: s.close()
except: pass
EOF
