void wdt_feed_the_dog(void)
{
  int fd;
  int ret;

  fd = open(wdog.devname, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "trace: cannot open %s\n", wdog.devname);
      return;
    }

  ret = ioctl(fd, WDIOC_KEEPALIVE, 0);
  if (ret < 0)
    {
      printf("watcher: ioctl(WDIOC_KEEPALIVE) failed: %d\n", ret);
    }

  close(fd);
}

